use serde_json::{json,Value};use sha2::{Digest,Sha256};use std::{fs,io::Read,path::{Path,PathBuf}};
const R:&str="/home/ubuntu/src/zopro-perf-work/balanced-kh-windows174";
fn r(p:impl AsRef<Path>)->PathBuf{Path::new(R).join(p)}
fn read(p:impl AsRef<Path>)->Value{serde_json::from_slice(&fs::read(p).unwrap()).unwrap()}
fn save(p:impl AsRef<Path>,v:&Value){fs::write(p,serde_json::to_vec_pretty(v).unwrap()).unwrap()}
fn hash(p:impl AsRef<Path>)->String{let mut f=fs::File::open(p).unwrap();let mut h=Sha256::new();let mut b=[0;65536];loop{let n=f.read(&mut b).unwrap();if n==0{break;}h.update(&b[..n]);}format!("{:x}",h.finalize())}
fn copy_dir(a:&Path,b:&Path){fs::create_dir_all(b).unwrap();for e in fs::read_dir(a).unwrap(){let e=e.unwrap();let p=e.path();if e.file_type().unwrap().is_dir(){copy_dir(&p,&b.join(e.file_name()));}else{fs::copy(p,b.join(e.file_name())).unwrap();}}}
fn prepare(){assert!(!r("repair-plan.json").exists());assert_eq!(read(r("native/failure.json"))["completed"].as_array().unwrap().len(),5);
 let before=r("before-test-brace-repair");fs::create_dir_all(&before).unwrap();copy_dir(&r("source"),&before.join("source"));copy_dir(&r("native"),&before.join("native"));
 for f in ["balanced.rs","build-pins.json","build-plan.json","native-workflow.log","native-workflow.stderr.log"]{fs::copy(r(f),before.join(f)).unwrap();}
 let before="\n            }\n        });}\n";let after="\n                }\n            }\n        });}\n";
 for f in ["balanced.rs","source/crates/zopro-core/src/msm_affine/borrowed_pending/balanced.rs"]{let p=r(f);let s=fs::read_to_string(&p).unwrap();assert_eq!(s.matches(before).count(),1);let fixed=s.replace(before,after);assert_eq!(s.split("#[cfg(test)]").next(),fixed.split("#[cfg(test)]").next());fs::write(p,fixed).unwrap();}
 let original=fs::read_to_string(r("native.rs")).unwrap();fs::write(r("native-repair.rs"),original.replace("native/libraries-{label}/stdout.log","native-repair/libraries-{label}/stdout.log")).unwrap();
 let mut steps=read(r("build-plan.json"))["steps"].as_array().unwrap()[5..].to_vec();assert_eq!(steps.len(),5);steps[3]["argv"][0]=json!(r("native-repair-helper"));save(r("repair-plan.json"),&json!({"version":1,"source_pins":r("repair-pins.json"),"steps":steps}));
 save(r("repair-note.json"),&json!({"reason":"missing closing brace in new test nested-loop block","runtime_module_prefix_byte_exact":true,"test_only_repair":true,"original_control_steps_reused":5,"remaining_candidate_steps":5,"initial_source_snapshot":"before-test-brace-repair/source","initial_native_receipts":"before-test-brace-repair/native","performance_capture_before_repair":false,"successful_tests_or_captures_repeated":false}));
}
fn pins(){let mut pins=serde_json::Map::new();for(p,h)in read(r("build-pins.json")).as_object().unwrap(){let current=hash(p);if current!=h.as_str().unwrap(){assert!(p==r("balanced.rs").to_str().unwrap()||p==r("source/crates/zopro-core/src/msm_affine/borrowed_pending/balanced.rs").to_str().unwrap());let rel=Path::new(p).strip_prefix(R).unwrap();assert_eq!(hash(r("before-test-brace-repair").join(rel)),h.as_str().unwrap());}pins.insert(p.clone(),json!(current));}
 for f in ["repair.rs","repair-helper","native-repair.rs","native-repair-helper","repair-plan.json","repair-note.json"]{pins.insert(r(f).display().to_string(),json!(hash(r(f))));}save(r("repair-pins.json"),&json!(pins));}
fn close(){assert_eq!(read(r("native-repair/result.json"))["status"],"complete");let before=read(r("native/failure.json"))["completed"].as_array().unwrap().clone();let mut completed=before.clone();for step in read(r("repair-plan.json"))["steps"].as_array().unwrap(){let name=step["name"].as_str().unwrap();copy_dir(&r(format!("native-repair/{name}")),&r(format!("native/{name}")));completed.push(json!(name));}fs::copy(r("native-repair/candidate-sdk"),r("native/candidate-sdk")).unwrap();assert_eq!(completed.len(),10);save(r("native-completion.json"),&json!({"unique_successful_steps":10,"original_control_five":before,"candidate_repaired_workflow":r("native-repair/result.json"),"original_runtime_prefix_exact":true,"successful_tests_repeated":false}));save(r("native/result.json"),&json!({"status":"complete","completed":completed,"merged_completion_index":true,"authoritative_receipts":[r("before-test-brace-repair/native/failure.json"),r("native-repair/result.json"),r("native-completion.json")]}));}
fn main(){match std::env::args().nth(1).as_deref(){Some("prepare")=>prepare(),Some("pins")=>pins(),Some("close")=>close(),_=>panic!("prepare/pins/close")}}
